const invoices = $('Fetch Open Invoices').all().map(i => i.json);
const history = $('Fetch Reminder History').all().map(i => i.json);
const sent = new Set(history.map(r => r.reminder_key || `${r.invoice_no}:${r.reminder_stage}`));
const today = new Date();
const out = [];
for (const inv of invoices) {
  const status = String(inv.payment_status || inv.status || '').toLowerCase();
  if (['paid','cancelled','disputed'].includes(status)) continue;
  const due = inv.due_date ? new Date(inv.due_date) : null;
  if (!due || Number.isNaN(due.getTime())) continue;
  const days = Math.floor((today - due) / 86400000);
  let stage = null;
  if (days < -1) continue;
  if (days <= 0) stage = 'due_today';
  else if (days <= 3) stage = 'overdue_3';
  else if (days <= 7) stage = 'overdue_7';
  else if (days <= 15) stage = 'overdue_15';
  else stage = 'final_notice';
  const key = `${inv.invoice_no || inv.id}:${stage}`;
  if (sent.has(key)) continue;
  out.push({ json: {
    business_id: inv.business_id || 'default',
    invoice_no: inv.invoice_no || inv.id,
    customer_name: inv.customer_name || '',
    customer_phone: String(inv.customer_phone || '').replace(/\D/g, ''),
    phone_number_id: inv.phone_number_id || 'YOUR_PHONE_NUMBER_ID',
    owner_phone: String(inv.owner_phone || '923000000000').replace(/\D/g, ''),
    amount_due: Number(inv.total || inv.amount_due || 0) - Number(inv.paid_amount || 0),
    due_date: inv.due_date,
    days_overdue: Math.max(0, days),
    reminder_stage: stage,
    reminder_key: key,
    needs_owner_approval: ['overdue_15','final_notice'].includes(stage) ? 'yes' : 'no',
    payment_link: inv.payment_link || '',
    created_at: new Date().toISOString()
  }});
}
return out;

const out = [];
for (const item of $input.all()) {
  const base = $('Build Reminder Queue').item.json;
  let ai = {};
  try { ai = JSON.parse(item.json.choices?.[0]?.message?.content || '{}'); } catch (e) { ai = {}; }
  const approval = base.needs_owner_approval === 'yes' || ai.needs_owner_approval === true;
  // An owner-approval request is logged under its own key so the customer stage stays
  // open. Logging it under the real stage key marked the stage as done, so the customer
  // was never chased for it afterwards - the escalation died silently.
  const loggedKey = approval ? base.reminder_key + ':approval_pending' : base.reminder_key;
  out.push({ json: { ...base, reminder_key: loggedKey, reminder_message: ai.message || `Please pay invoice ${base.invoice_no} amount Rs ${base.amount_due}.`, tone: ai.tone || 'firm', needs_owner_approval: approval ? 'yes' : 'no', ai_reason: ai.reason || '', status: approval ? 'approval_required' : 'ready_to_send' } });
}
return out;
